//! Traditional carol melodies, all long in the public domain (written down
//! 1582–1857), as plain note lists. Only the tunes are taken; harmony and
//! arrangement are generated by `music.rs`.
//!
//! Token format: `NOTE:UNITS` (e.g. `F#4:3`, `R:2` for a rest); `|` marks
//! bars for readability and is ignored. `unit` = beats per duration unit.

pub struct Tune {
    pub name: &'static str,
    /// Beats per duration unit.
    pub unit: f32,
    /// Beats per bar.
    pub bar: f32,
    /// Beats before the first full bar.
    pub pickup: f32,
    /// Pitch class of the key's tonic (all are major keys).
    pub tonic: i32,
    /// Comfortable tempo range, beats per minute.
    pub tempo: (f32, f32),
    /// Suits the upbeat sleigh-ride arrangement.
    pub lively: bool,
    pub notes: &'static str,
}

