/// Parse a tune's notes into (start beat, length in beats, MIDI note);
/// rests are skipped.
pub fn parse(t: &Tune) -> Vec<(f32, f32, i32)> {
    let mut out = vec![];
    let mut at = 0.0;
    for tok in t.notes.split_whitespace() {
        if tok == "|" {
            continue;
        }
        let Some((name, units)) = tok.split_once(':') else { continue };
        let len = units.parse::<f32>().unwrap_or(1.0) * t.unit;
        if let Some(m) = note_midi(name) {
            out.push((at, len, m));
        }
        at += len;
    }
    out
}

fn note_midi(s: &str) -> Option<i32> {
    let mut ch = s.chars();
    let pc = match ch.next()? {
        'C' => 0,
        'D' => 2,
        'E' => 4,
        'F' => 5,
        'G' => 7,
        'A' => 9,
        'B' => 11,
        _ => return None, // rest
    };
    let rest: String = ch.collect();
    let (acc, oct) = if let Some(r) = rest.strip_prefix('#') {
        (1, r)
    } else if let Some(r) = rest.strip_prefix('b') {
        (-1, r)
    } else {
        (0, rest.as_str())
    };
    let oct: i32 = oct.parse().ok()?;
    Some(12 * (oct + 1) + pc + acc)
}
